SELECT CASE WHEN m.entry_quality_score < 55 THEN 'a50-54' WHEN m.entry_quality_score < 70 THEN 'b55-69' WHEN m.entry_quality_score < 85 THEN 'c70-84' ELSE 'd85+' END AS eq_band, p.status, COUNT(*) AS n, SUM(p.realized_pnl < 0) AS losses, ROUND(SUM(p.realized_pnl), 6) AS pnl_sum, ROUND(AVG(m.profit_lock_progress_percent), 2) AS avg_progress_pct FROM paper_position p JOIN wallet_managed_position m ON m.entry_signal_id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at IS NOT NULL GROUP BY eq_band, p.status ORDER BY eq_band, p.status